export default [{"id":2738,"question":"من كان عليه دَيْن يُعذّب في قبره؟","title":"هل الدَّين من أسباب عذاب القبر؟","answer":"الجواب: إذا كان مفرِّطًا ومتساهلًا هذا من الذنوب، على خطر. أما إن كان معسرًا، ما هو بهواه، ما عليه خطر وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280].","link":"https://binbaz.org.sa/fatwas/22886/هل-الدين-من-اسباب-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعذب من كان عليه دين في القبر.mp3","categories":["عذاب القبر ونعيمه "]},{"id":2941,"question":"تبليغ الملائكة صلاة النبي ﷺ إلى النبي ﷺ، بعضهم يستدلّ على أن النبي ﷺ حيٌّ في قبره؟","title":"هل النبي عليه الصلاة والسلام حَيٌّ في قبره؟","answer":"الجواب: رُوحُه في الجنة، يُبَلَّغ، روحه في الجنة في أعلى علّيين عليه الصلاة والسلام، يبلّغونه، روحه حية، الأرواح ما تموت، تموت الأبدان، موت الأرواح خروجها من البدن، هذا الموت، مثل ما جاء في الحديث الصحيح: إن أرواح المؤمنين طائر يَعْلَق في شجر الجنة، وأرواح الشهداء في أجوفة طير خُضْر تسرح في الجنة حيث شاءت، ثم تعود إلى قناديل معلقة تحت العرش. الأبدان هي التي تفنى إلا عَجْب الذَّنَب، والأرواح باقية، أرواح أهل الإيمان في الجنة وأرواح الكافرين في النار، نسأل الله العافية، وإذا أراد الله ردّها إلى جسدها بعض الأحيان؛ فلا مانع.","link":"https://binbaz.org.sa/fatwas/23097/هل-النبي-عليه-الصلاة-والسلام-حي-في-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النبي حي في قبره.mp3","categories":["عذاب القبر ونعيمه "]},{"id":3018,"question":"ما ثبت أن الشهداء لا تأكل الأرضُ أجسادَهم؟","title":"هل تأكلُ الأرضُ أجسادَ الشهداء؟","answer":"الجواب: ما أعرف هذا، إنما جاء في الأنبياء أن الله حَرَّم عليها أن تأكل أجساد الأنبياء، لكن قد يقع هذا لبعض الأخيار كرامة من الله  وإذا أخذته الأرض فلا يضر كل الناس مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ [طه:55]، لكن يَفْنى من ابن آدم كل شيء إلا عَجْبُ الذَّنَبِ، عُظَيْمة في المقعدة، يبقى، يُرَكَّب منها الخَلْقُ يوم القيامة.","link":"https://binbaz.org.sa/fatwas/23176/هل-تاكل-الارض-اجساد-الشهداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأرض تأكل أجساد الشهداء.mp3","categories":["عذاب القبر ونعيمه "]},{"id":4132,"question":"بالنسبة للعُصاة الذين يدخلون النار ويطهرون منها، كيف حالهم في القبر؟","title":"هل تتفاوت أحوال العصاة في القبور؟","answer":"الجواب: أقسام، هم أقسام، والله أعلم بحالهم: منهم مَن يُعذَّب، ومنهم مَن لا يُعذَّب، ومنهم مَن يُعذَّب بعض الأحيان ويُترك، الله جلَّ وعلا جعلهم في برزخ يقال لهم: ذو الشائبتين، ذكر أحوال أهل الإيمان وسلامتهم، وذكر الكفار وعذابهم.  وأما ذو الشائبتين -وهم العُصاة- ففي غالب النصوص السكوت عنهم في حال القبر، وفي بعض النصوص بيان ما يُصيبهم في القبر؛ كالذي عُذِّب في القبر بسبب عدم تنزهه من البول، والذي عُذِّب بسبب النميمة، نسأل الله العافية.\nوالحاصل أنهم على خطرٍ من العذاب في النار وفي القبر جميعًا، لكن ليسوا من الكفار، الكفَّار عذابهم مُحتَّم، أما العُصاة فهم قد يُعفى عن بعضهم لحسناتٍ وأعمالٍ صالحات؛ عمل صالح رَجُح بسيئاته، وقد يكون يُعذَّب بعض الوقت ويُعفى عنه، قد يُؤجل عذابه إلى النار، فهم تحت مشيئة الله ، تفصيل أمرهم إلى الله جل وعلا.","link":"https://binbaz.org.sa/fatwas/24378/هل-تتفاوت-احوال-العصاة-في-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حال العصاة في القبر.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5117,"question":"تقول في سؤالها الأخير: هل تتلاقى الأرواح بعد الموت؟","title":"هل تتلاقى الأرواح بعد الموت؟","answer":"الجواب: الله أعلم، جاء فيها مَرَاءٍ كثيرة في التلاقي، والله أعلم ، جاء أشياء تدل على أنها قد تتلاقى روح المؤمن مع روح المؤمن الحي في النوم، وقد وجد في هذا أمثلة كثيرة تدل على وجود ذلك، ولكن ليس في هذا أحاديث صحيحة عن النبي ﷺ تدل على ذلك فيما نعلم، ولكن وجد منامات تدل على هذا وعلى وقوعه.","link":"https://binbaz.org.sa/fatwas/30025/هل-تتلاقى-الارواح-بعد-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 47.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5132,"question":"سائل يقول: ما عقيدة أهل السنة والجماعة في عذاب القبر؟ وهل هو على الروح فقط أم على الروح والجسد؟","title":"ما عقيدة أهل السنة والجماعة في عذاب القبر؟","answer":"الجواب: من عقيدة أهل السنة والجماعة: الإيمان بعذاب القبر ونعيمه، فالميت إمَّا أن يُنَعَّم، وإمَّا أن يُعَذَّب، فأهل السنة والجماعة يؤمنون بذلك، وقد أخبر النبيُّ عليه الصلاة والسلام بهذا، فالقبر إمَّا روضة من رياض الجنة، وإما حُفرة من حُفر النار. فعلى المسلم أن يؤمن بهذا، وقد أطلع الله نبيَّه ﷺ على شخصين يُعذَّبان: أحدهما كان يمشي بالنَّميمة، والآخر كان لا يَتَنَزَّه من البول. فأهل السنة يؤمنون بعذاب القبر ونعيمه، وأنه حقٌّ على الروح والجسد جميعًا، ولكن نصيب الروح أكثر، كما قال الله جلَّ وعلا في آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا [غافر:46]، وهكذا الميت الصالح يُنَعَّم في قبره، وغير الصالح يُعَذَّب في قبره، ويوم القيامة العذاب أشد، والنعيم أعظم بعد البعث يوم النُّشور.","link":"https://binbaz.org.sa/fatwas/30047/ما-عقيدة-اهل-السنة-والجماعة-في-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 68.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5376,"question":"الأنبياء والصِّديقون والشهداء والأطفال لا يُفتنون في قبورهم؟","title":"هل يُفتن الأنبياء والشهداء والأطفال في قبورهم؟","answer":"الجواب: الله أعلم، أما الأنبياء فالظاهر -والله أعلم- أنهم لا يُفتنون؛ لأنَّ الله قد صانهم وحماهم، وأما غيرهم فكلّ يُفتن إلا الأطفال، الأطفال ما كُلِّفوا، الأطفال ما عليهم فتنة؛ لأنهم ما كُلِّفوا، أما غيرهم فكلّ يُمتحن في قبره ما عدا الأنبياء - عليهم الصلاة والسلام - فمعلوم أنهم لهم العصمة. س: الشهيد يُفتن في قبره؟ ج: يُنظر في الأحاديث الواردة في ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31111/هل-يفتن-الانبياء-والشهداء-والاطفال-في-قبورهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya006.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5378,"question":"سماع الميت في قبره، يسمع؟","title":"ما الصواب في سماع الميت في قبره؟","answer":"الجواب: الله أعلم، أما النبي ﷺ فقال: فإنها تُرد عليَّ روحي حتى أردَّ عليه السلام، أما الأموات ففي الحديث هذا الذي رواه ابن عبد البر: ما من مسلمٍ يمر على قبرٍ كان يعرفه في الدنيا ويُسلم عليه إلا ردَّ الله عليه روحه، هذا إنْ صحَّ يكون خاصًّا، إنْ صحَّ، أما حديث أنه يسمع قرع نعالهم، هذه خاصة أول ما يُدفن، حين تُرد إليه روحه حتى يُجيب الملائكة، يسمع قرع نعال الذين ولَّوا مُدبرين عنه ممن شيَّعه، وليس هذا دالًّا على أنه دائمًا يسمع، هذه أمور غيبية لا يثبت منها شيء إلا بالدليل، أمور غيبية لا يجوز أن يثبت منها شيء إلا بالدليل الثابت، فالأصل أنهم لا يسمعون؛ قال الله تعالى: إِنَّكَ لَا تُسْمِعُ الْمَوْتَى [النمل:80]، وقال تعالى: وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ [فاطر:22]، فالأصل أنهم لا يسمعون، إذا مات الميتُ انقطع عمله إلا ما دلَّ عليه الدليل. س: حديث أبي سعيدٍ الخدري في \"الصحيحين\" أن النبي ﷺ قال: إذا وُضعت الجنازة فاحتملها الرجالُ على أعناقهم، فإن كانت صالحةً قالت: قدِّموني، وإن كانت غير صالحةٍ قالت: يا ويلها! أين يذهبون بها؟! ج: هذا خاص في هذه الحالة، هذا بالنص لهذه الحالة، ما يلزم أنها في كل وقتٍ تسمع أو تقول، إنما يُوقف عند النصوص فقط، لا يُزاد على النصوص.[1]","link":"https://binbaz.org.sa/fatwas/31112/ما-الصواب-في-سماع-الميت-في-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya007.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5482,"question":"منكر عذاب القبر هل يكون كافرًا يُستتاب؟","title":"ما حكم مَن يُنكر عذاب القبر؟","answer":"الجواب: يُستتاب، فإن تاب وإلا قُتل؛ لأنه مكذب للرسول ﷺ، وإذا كان جاهلًا يُعلَّم، وإذا أصرَّ يكفر بذلك.[1]","link":"https://binbaz.org.sa/fatwas/31379/ما-حكم-من-ينكر-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 007.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5707,"question":"قال تعالى: وَقُلِ اعْمَلُواْ فَسَيَرَى اللّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ [التوبة:105]، هل الميت يعرف، ويعرض عليه أعمال أهله؟ وهل يعلم بهم عند الزيارة؟","title":"حقيقة معرفة الميت أهله وعرض أعمالهم عليه","answer":"الجواب:  كون الميت يعرف أهله، ويعرف زواره محل نظر، وليس عليه دليل، والمراد بالآية -والله أعلم-: أن الله يراهم دائمًا  يرى عمل الناس، والمؤمنون يرونه في الدنيا أعمالهم، وتنشر يوم القيامة بين الناس، وهكذا الرسول يراها في الدنيا حين حياته، ويراها يوم القيامة حين تنشر بين الناس على رؤوس الأشهاد.  ففي هذا المعنى الحث على العمل الصالح، وأنه سوف ينشر، يراه أهل الإيمان في الدنيا، ويراه الله  فيراه المؤمنون يوم القيامة، ويراه الرسول يوم القيامة، ويراه في حياته فيما بين أصحابه، رضي الله عنهم وأرضاهم. فالحث على العمل الصالح، وإظهاره؛ لأن هذا يشرف الإنسان، ويعمل الصالحات، ويجتهد في الخيرات، فإن هذا سوف يراه المؤمنون في الدنيا، ويثنى عليه، وينشر له ذكر طيب بين الناس، وفي الآخرة ينشر بين الناس، ويقال: هذا عمل فلان، وينادى عليه، ويثقل ميزانه، وله خير عظيم يوم القيامة، والضد بالضد، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1008/حقيقة-معرفة-الميت-اهله-وعرض-اعمالهم-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_34.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5805,"question":"ورد في المحاضرة: أن الميت المسيئ يعذب في قبره تعذيبًا برزخيًّا، وقلتم أن المسيئ يفتن في قبره، فكيف تكون الفتنة؟ وهل هناك من يفتنه غير الشيطان؟","title":"ما المقصود بفتنة القبر؟","answer":"الجواب:  الفتنة في القبور معناها الابتلاء، والامتحان الشيطان راح، راح دور الشيطان بعد الموت، راح دور الشيطان، وجاء دور الملائكة، فالفتنة التي للشيطان هذا قبل الموت، أما بعد الموت مثل ما قال الله: ذُوقُوا فِتْنَتَكُمْ [الذاريات:14]. فالمقصود: أنهم يفتنوا في القبور فتنة معناها الامتحان والاختبار، والإحراق بالنار يسمى فتنة أيضًا، فالميت إن أجاب السؤال جوابًا صحيحًا فله الجنة، والكرامة، وقبره روضة من رياض الجنة.  وإن أجاب جوابًا سيئًا، فقال: هاه هاه لا أدري، سمعت الناس يقولون شيئًا فقلته، فإنه يضرب بمرزبة من حديد يصيح بها صيحة يسمعها كل شيء إلا الإنسان، هذا يعاقب في قبره، ويعذب -والعياذ بالله- والنبي ﷺ أطلعه على قبرين يعذبان، قال: وما يعذبان في كبير ثم قال: بلى، إنه لكبير، أما أحدهما: فكان لا يستتر من البول يعني: لا يستنزه منه، كما في رواية أخرى وأما الآخر: فكان يمشي بالنميمة نقل الكلام السيئ بين الناس بعضهم إلى بعض، هذا وعيد شديد يدل على أن من مات على النميمة، وعدم التنزه من النجاسات فهو على خطر من العقاب في قبره، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1132/ما-المقصود-بفتنة-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_138.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5822,"question":"ورد في المحاضرة: أن الميت المسيئ يعذب في قبره تعذيبًا برزخيًّا، وقلتم أن المسيئ يفتن في قبره، فكيف تكون الفتنة؟ وهل هناك من يفتنه غير الشيطان؟","title":"ما المقصود بفتنة القبر؟","answer":"الجواب:  الفتنة في القبور معناها الابتلاء، والامتحان الشيطان راح، راح دور الشيطان بعد الموت، راح دور الشيطان، وجاء دور الملائكة، فالفتنة التي للشيطان هذا قبل الموت، أما بعد الموت مثل ما قال الله: ذُوقُوا فِتْنَتَكُمْ [الذاريات:14]. فالمقصود: أنهم يفتنوا في القبور فتنة معناها الامتحان والاختبار، والإحراق بالنار يسمى فتنة أيضًا، فالميت إن أجاب السؤال جوابًا صحيحًا فله الجنة، والكرامة، وقبره روضة من رياض الجنة.  وإن أجاب جوابًا سيئًا، فقال: هاه هاه لا أدري، سمعت الناس يقولون شيئًا فقلته، فإنه يضرب بمرزبة من حديد يصيح بها صيحة يسمعها كل شيء إلا الإنسان، هذا يعاقب في قبره، ويعذب -والعياذ بالله- والنبي ﷺ أطلعه على قبرين يعذبان، قال: وما يعذبان في كبير ثم قال: بلى، إنه لكبير، أما أحدهما: فكان لا يستتر من البول يعني: لا يستنزه منه، كما في رواية أخرى وأما الآخر: فكان يمشي بالنميمة نقل الكلام السيئ بين الناس بعضهم إلى بعض، هذا وعيد شديد يدل على أن من مات على النميمة، وعدم التنزه من النجاسات فهو على خطر من العقاب في قبره، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1132/ما-المقصود-بفتنة-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_138.mp3","categories":["عذاب القبر ونعيمه "]},{"id":5833,"question":"هل يحس الموتى في قبورهم بمن يسلم عليهم، ويزورهم؟","title":"هل يشعر الموتى بمن يزورونهم","answer":"الجواب: الله أعلم، ذكر بعض أهل العلم أنهم يشعرون بهذا، وأنهم يأنسون بهذا الشيء، ولكن أنا ما وجدت ما علمت شيئًا بالسنة يدل على ذلك؛ فالله أعلم .  والمشروع لنا: أن نزورهم، وندعو لهم عند القبور، وفي بيوتنا، وفي كل مكان، ندعو لموتى المسلمين، ونترحم عليهم، هذا ينفعهم، وهكذا الصدقة عنهم تنفعهم، أما كونهم يشعرون بالزائر، ويعلمون الزائر فالله أعلم، لا أعلم شيئًا واضحًا يدل على ذلك.","link":"https://binbaz.org.sa/fatwas/1160/هل-يشعر-الموتى-بمن-يزورونهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_159.mp3","categories":["عذاب القبر ونعيمه "]},{"id":6290,"question":"هل الصيحة على الكل، لأنني سمعت أحدهم يقول: إن الناس إذا راحوا عنه؟","title":"صياح بعض الموتى في القبور","answer":"الجواب:  لا هذا يسمع قرع النعال فقط، وإلا ما في صيحة، الصيحة لمن يضرب، لكن لا يسمعها الناس في الغالب، ما يسمعها الناس، وإلا قد يسمع، لكنه نادر، نسأل الله العافية. حدثني بعض الناس منذ ثلاثين سنة تقريبًا أن له عمة توفيت، فقيل لهم: إن في قبرها صياحًا، وكان يستبعد هذا الشيء، فظهر مرة من المرات، واستمع إلى قبرها، فإذا هو صحيح، فإذا فيه صياح، وسئل عنها أصحابها؛ فقالوا: إنها لا تزكي، عندها أموال وهي لا تزكي، وأن هذا من جزائها، نسأل الله السلامة والعافية، ولا حول ولا قوة إلا بالله. والنبي ﷺ مر على قبرين، أطلعه الله على عذابهما، سمعتم ما تقدم، وأن أحدهما كان يمشي بالنميمة، والآخر كان لا يتنزه من البول -نعوذ بالله- وجاء وقائع أخرى، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1800/صياح-بعض-الموتى-في-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_641.mp3","categories":["عذاب القبر ونعيمه "]},{"id":6892,"question":"المسلم الذي يوجب الله عليه النار، ويدخل فيها، هل يحس بالعذاب أم لا؟","title":"الفرق بين عذاب أهل المعاصي وعذاب الكفار في النار","answer":"الجواب: الذي يحكم الله عليه بالنار يحس بعذابها، ويحس بنكالها، ولكن جاء في حديث أبي سعيد عند مسلم -رحمه الله- قال: فتميتهم إماتة يعني تأخذهم النار، وتحرقهم، ويموتون.. يعني يحسون بعذابها، وآلامها، ويميتون فيها موتة خاصة، ثم يخرجهم الله من النار، وقد احترقوا أمثال الفحم، ثم يلقون في نهر الحياة، فينبتون كما تنبت الحبة في حميل السيل، يحرقون، ويحسون بالآلام، ولكنهم بعد ذلك ينبتون نباتًا جديدًا، الله -جل وعل-ا على كل شيء قدير  ليسوا مثل الكفرة، الكفرة يبقون في النار لا حياة ولا موت أبد الآباد، ودهر الداهرين أبدًا -نعوذ بالله- لَا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا [فاطر:36]. وهكذا قوله: إِنَّهُ مَنْ يَأْتِ رَبَّهُ مُجْرِمًا فَإِنَّ لَهُ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَى [طه:74] -نعوذ بالله-. وقال -جل وعلا-: وَيَتَجَنَّبُهَا الْأَشْقَى  ۝  الَّذِي يَصْلَى النَّارَ الْكُبْرَى  ۝  ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَى [الأعلى:11-13] يعني معذب، لا موت يريحه، ولا حياة سليمة -نعوذ بالله- بل هو في عذاب دائم -نعوذ بالله- هذا معنى لا يموت ولا يحيى -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/2783/الفرق-بين-عذاب-اهل-المعاصي-وعذاب-الكفار-في-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1275.mp3","categories":["عذاب القبر ونعيمه "]},{"id":7599,"question":"هذا المستمع الأخ (م. ج. م) يسأل عن الميت -عن حساب الميت- يقول: هل هو الحساب فوري يدخل على الجنة أم على النار؟ أم يتأجل إلى يوم القيامة للحساب، أفيدونا هداكم الله؟","title":"القبر روضة من رياض الجنة أو حفرة من حفر النار","answer":"الجواب: جاء في النصوص عن النبي ﷺ ما يدل على أن القبر إما روضة من رياض الجنة وإما حفرة من حفر النار، وأن العبد إذا قبض يبشر عند قبره بالجنة إن كان مؤمناً ويبشر بالنار إن كان كافراً، فإذا دخل قبره وسئل عما يجب فلم يجب عذب في قبره، وهذا العذاب مبدأ للعذاب في الآخرة، كما أن المؤمن إذا دخل قبره ينعم في قبره ويفتح له باب إلى الجنة يأتيه من نعيمها وطيبها، ويرى مقعده منها، ويرى مقعده من النار، وأن الله كفاه ذلك وعافاه من ذلك، فالكافر كذلك يرى مقعده من الجنة وأنه حيل بينه وبينها بسبب كفره، ويرى مقعده من النار فيأتيه من سمومها وعذابها ونكالها، وقبره يكون حفرة من حفر النار يعذب فيه على قدر أعماله السيئة وكفره بالله عز وجل. \nفالقبر مبدأ من مبادئ النعيم في حق المؤمن، ومبدأ من مبادئ العذاب في حق الكافر، والعاصي على خطر، العاصي الذي مات على معاصي قد يعذب في قبره وإن كان غير كافر لكن ثبت عن رسول الله عليه الصلاة والسلام «أنه اطلع على قبرين يعذبان، فأما أحدهما فكان يمشي بالنميمة، وأما الآخر فكان لا يستتر من البول -يعني: لا يستنزه من البول- فأخبر أنهما عذبا بسبب هذه المعصية»، وفي الحديث الآخر: «أكثر عذاب القبر من البول» «استنزهوا من البول فإن عامة عذاب القبر منه»، فدل ذلك على أن المعاصي قد يعذب أهلها في القبر بسببها، وبهذا تعلم أن القبر إما محل عذاب وإما محل نعيم، ولكنه عذاب مقدم ونموذج لعذاب النار، ونعيم مقدم ونموذج من نعيم الجنة. \nفينبغي للمؤمن الحذر والاستعداد للآخرة وأن يتأهب للقاء الله، وأن يحذر أسباب العذاب، وذلك بالاجتهاد في طاعة الله والاستقامة على أمر الله، والبعد عن معاصي الله، والتواصي بالحق والصبر عليه، حتى تلقى ربك وأنت على هذه الحال، تلقى ربك وأنت مجتهد في طاعة الله، ومبتعد عن محارم الله واقف عند حدود الله، تعين إخوانك على الخير وتوصيهم بالحق والصبر عليه. \nهكذا يكون المؤمن حتى يلقى ربه عز وجل يكون صابراً مصابراً، يتباعد عن كل ما حرم الله ويسارع إلى مراضي الله، حتى يلقى ربه عز وجل، وبهذا يكون في قبره في نعيم وخير عظيم، وفي روضة مستمرة من رياض الجنة حتى يلقى ربه عز وجل فيحصل له ما هو أكبر وأعظم من نعيم الجنة، والعكس بالعكس، الكافر بخلاف ذلك إذا مات صار في عذاب ونكال وما بعده شر منه، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/4652/القبر-روضة-من-رياض-الجنة-او-حفرة-من-حفر-النار ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02007.mp3","categories":["عذاب القبر ونعيمه "]},{"id":8020,"question":"شيخ عبد العزيز! هذه رسالة وردتنا من فتحي محمد مؤمن من جمهورية مصر العربية، يقول في رسالته: سمعت من بعض العلماء بأن الميت إذا أتي به إلى القبر ليدفن فإنه يسمع كل ما يقول الناس الذين أتوا لدفنه، فهل هذا صحيح أم لا؟","title":"مدى صحة القول بسماع الميت كلام الناس الذين دفنوه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفأمور البرزخ وأمور الأموات من الأمور العظيمة الغيبية التي لا يطلع عليها إلا الله سبحانه وتعالى، وما يقوله الناس في هذا الباب لا يعتمد عليه وإنما الثابت عن النبي عليه الصلاة والسلام أنه قال: إنه ليسمع قرع نعالهم يعني: بعد انصرافهم وبعد الدفن، هذا هو المحفوظ، أما سماع ما يقول الناس وما يتحدثون به فلم يرد فيه شيء فيما نعلم ولا يجوز الجزم بذلك إلا بدليل، هو عليه الصلاة والسلام ذكر أنه يسمع قرع نعالهم إذا انصرفوا من دفنه فلا يجوز للمؤمن ولا لغيره أن يجزم بشيء عن الأموات إلا بدليل. نعم.","link":"https://binbaz.org.sa/fatwas/5583/مدى-صحة-القول-بسماع-الميت-كلام-الناس-الذين-دفنوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_077/07701.mp3","categories":["عذاب القبر ونعيمه "]},{"id":8825,"question":"أخونا أيضاً يسأل سؤال يتعلق بالعقيدة في الواقع سماحة الشيخ يقول: إنني مؤمن بالله وأصدق بما جاء في الكتاب العزيز ولكن الذي يثير الشك عندي هو إحياء الميت في القبر، سؤالي: هل هي نفس حياته الأولى، وكم حاسة ترجع إليه، وإلى متى تبقى حياته في القبر، وإذا كان الميت تسأل جثته فما مصير الذين يحرقون أو يحرقون مثل الهند وألبانيا وغيرهم، وأين يتم سؤالهم، إن الطبيب يا سماحة الشيخ عندما يجري العملية يبعد حواس الإنسان عنه بمخدر أما هذا الموت فإنني لازلت أتساءل وأبدي لكم أنني غير ساخر لكنني في حيرة وأرجو الإيضاح عبر هذا البرنامج المفيد، جزاكم الله خيراً؟","title":"هل حياة الموتى في قبورهم كحياتهم في الدنيا؟","answer":"الجواب: أولاً: ينبغي أن يعلم أن الواجب على كل مؤمن وعلى كل مؤمنة التصديق بما أخبر الله به في كتابه، أو على لسان رسوله محمد صلى الله عليه وسلم من جميع الأمور فيما يتعلق بالآخرة والحساب والجزاء والجنة والنار وفيما يتعلق بالموت والقبر وعذابه ونعيمه، على المؤمن أن يصدق بما أخبر الله به ورسوله، فما جاء في القرآن العظيم أو صحت به السنة فعلينا الإيمان والتسليم والتصديق؛ لأنا نعلم أن ربنا هو الصادق في قوله، قال سبحانه: وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلًا [النساء:122] وَمَنْ أَصْدَقُ مِنَ اللَّهِ حَدِيثًا[النساء:87]، ونعلم أن الرسول ﷺ أصدق الناس وأنه لا ينطق عن الهوى إن هو إلا وحي يوحى، فما ثبت عنه في الأحاديث الصحيحة وجب التصديق به، وإن لم نعرف هنا وإن لم نعرف حقيقته نصدق بما أخبر به من أمر الآخرة أمر الجنة أمر النار عذاب أهل النار، نعيم أهل الجنة، كون العبد في قبره يعذب أو ينعم ترد إليه روحه.. يسأل كل هذا حق جاءت به النصوص، والأحاديث الصحيحة، فعلى العبد أن يسلم وأن يصدق بكل ما علمه من القرآن العظيم أو صحت به السنة عن رسول الله ﷺ أو أجمع عليه علماء الإسلام.\nثم إذا من الله على المؤمن أو المؤمنة بالعلم بالحكم والأسرار فهذا خير إلى خير، ونور إلى نور، وعلم إلى علم، فليحمد الله وليشكره على ما أعطاه من البصيرة في الحكم والأسرار التي من الله عليه بها حتى زاد علمه وحتى زادت طمأنينته.\nأما ما يتعلق بسؤال الأخ عن حال القبر وعن حال الميت فإن السؤال حق فإن الميت ترد إليه روحه إذا مات وقد صحت به الأخبار عن رسول الله ﷺ ترد إليه روحه فيسأل في قبره على كيفية الله أعلم بها حياة غير حياته الدنيوية حياة خاصة برزخية ليست من جنس حياته في الدنيا التي يحتاج فيها إلى الطعام والشراب ونحو ذلك لا بل حياة خاصة يعقل معها السؤال والجواب، ثم ترجع روحه بعد ذلك إلى عليين إن كان من أهل الإيمان إلى الجنة، وإن كان من أهل النار إلى النار، لكنها تعاد إليه وقت السؤال والجواب فيسأله الملكان: من ربك؟ ما دينك؟ من نبيك؟ فالمؤمن يقول: ربي الله والإسلام ديني ومحمد نبيي، هكذا المؤمن والمؤمنة، ويقال له: ما علمك بهذا الرجل يعني: محمد. فيقول: هو رسول الله جاءنا بالهدى فآمنا به وصدقناه واتبعناه فيقال له: نم صالحاً قد علمنا إن كنت لمؤمناً ويفتح له باب إلى الجنة فيأتيه من روحها ونعيمها ويقال له: هذا مكانك في الجنة حتى يبعثك الله إليه ويفتح له باب إلى النار فيرى مقعده من النار والله على كل شيء قدير، هذه أمور عظيمة غيبية فيرى مقعده ويقال له: هذا مكانك لو كفرت بالله، أما الآن فقد عافاك الله منه وصرت إلى الجنة، وهكذا يقال للكافر، فإذا سئل قال الكافر: هاه هاه! لا أدري سمعت الناس يقولون شيئاً فقلته، فيضرب بمرزبة يعني: مطرقة من حديد فيصيح صيحة يسمعه كل شيء يسمعها كل شيء إلا الثقلين إلا الإنس والجن، يسمعها البهائم، فيقال له: قد علمنا أنك غير مؤمن وعلى هذا عشت وعليه مت فيفتح عليه باب إلى النار ويضيق عليه قبره حتى تختلف أضلاعه ويكون قبره عليه حفرة من حفر النار نعوذ بالله، ويفتح له باب إلى النار فيأتيه من سمومها وعذابها ويقال: هذا مكانك حتى يبعثك الله إليه، ويفتح له باب إلى الجنة فيرى مقعده من الجنة لو هداه الله، ولكن الله صرفه عنه لما كفر بالله وربك أحكم وأعلم سبحانه وتعالى.\nفالقبر إما روضة من رياض الجنة وإما حفرة من حفر النار، والعذاب والنعيم للروح والجسد جميعاً في القبر للروح والجسد، وهكذا في الآخرة في الجنة للروح والجسد في النار للروح والجسد، أما من مات بغرق مات بالحرق مات بأكل السباع فإن روحه يأتيها نصيبها من العذاب والنعيم، ويأتي جسده من ذلك في البحر أو في الحرق أو في بطون السباع أو غيره، يأتيه نصيبه من ذلك على الوجه الذي يعلمه الله سبحانه وتعالى، لكن المعظم والمهم على الروح التي تبقى فهي إما منعمة وإما معذبة.\nفإن ما أكله السباع ذهبت الروح إلى مكانها من خير وشر، وهكذا من أحرقته النار أو سقط في البحار وأكلته حيتان البحر أو غير ذلك الأرواح تذهب إلى مكانها، المؤمن تذهب روحه إلى الجنة، قال النبي ﷺ: إن روح المؤمن طائر يعلق في شجر الجنة يأكل من ثمارها، والكافر تذهب روحه إلى النار وإلى ما شاء الله من عذاب الله وإن ذهب جسده في الحرق أو في السباع أو في غير ذلك.\nفينبغي لك أيها السائل وأيها المؤمن وأيها المؤمنة أن تطمئن إلى ما أخبر الله به ورسوله، وأن كون الإنسان يحرق أو تأكله السباع أو يذهب في البحار أو غير ذلك كل هذا لا يمنع من العذاب والنعيم، فالنعيم والعذاب يصل إليه كما يشاء الله سبحانه وتعالى، ومعظمه في القبر على الروح نعيماً أو شراً، وينال الجسد نصيبه من ذلك، وعند بعثه ونشوره يجمع الله له ما وعده به من خير وشر لروحه وجسده، فالروح والجسد يوم القيامة منعمان أو معذبان، جميعاً إما في النار وهم الكفار وإما في الجنة وهم أهل الإيمان.\nأما العصاة فلهم نصيبهم العصاة لهم نصيبهم بين الجنة والنار، بين هؤلاء وهؤلاء إن عفا الله عنهم ألحقوا بأهل الإيمان وصاروا إلى الجنة والكرامة وسلموا من عذاب القبر ومن عذاب النار، وإن لم يعف عنهم بسبب معاصيهم من الزنا أو شرب الخمر أو العقوق للوالدين أو قطيعة الرحم أو أكل الربا أو غير هذا إذا لم يعف عنهم نالهم نصيبهم من العذاب في القبر على قدرهم لكنهم دون الكفار أقل من الكفار، ويوم القيامة يدخلهم الله النار ويعذبون على قدر معاصيهم إن لم يعف الله عنهم، فإذا طهروا في النار وخلصوا من خبث معاصيهم أخرجهم الله من النار إلى الجنة، بفضل رحمته سبحانه وتعالى، وقد يخرجون بشفاعة الشفعاء كشفاعة النبي ﷺ وشفاعة الملائكة والأنبياء والمؤمنين والأفراط ويبقى في النار من العصاة من شاء الله فيخرجهم الله برحمته سبحانه من غير شفاعة أحد، بل بمجرد فضله ورحمته جل وعلا؛ لأنهم ماتوا على التوحيد، فيخرجهم الله من النار بعدما يجازون إذا لم يعف عنهم قبل ذلك، ولا يبقى في النار إلا الكفرة مخلدون فيها أبد الآباد يبقى الكفار مخلدين في النار أبد الآباد، أما العصاة الذين ماتوا على معاصي لم يتوبوا فهم تحت مشيئة الله سبحانه وتعالى، إن شاء عفا عنهم بأعمالهم الطيبة وتوحيدهم وإن شاء عاقبهم وعذبهم في القبر وفي النار على قدر معاصيهم، ولكنهم لا يخلدون خلوداً دائماً أبداً لا بل يقيمون في النار إذا دخلوها مدداً متفاوتة على حسب أعمالهم السيئة، فإذا انتهت عقوبتهم أخرجهم الله من النار إلى الجنة، هذا قول أهل السنة والجماعة قاطبة خلافًا للخوارج والمعتزلة فإن الخوارج و المعتزلة يقولون: العصاة إذا دخلوا النار لا يخرجون أبداً كالكفار، وهذا قول باطل، والذي عليه أهل السنة والجماعة وهم أصحاب النبي صلى الله عليه وسلم وأتباعهم بإحسان أن العصاة إذا لم يعف عنهم ودخلوا النار لا يخلدون بل يعذبون عذاباً متفاوتاً على قدر معاصيهم مدداً يشاؤها الله سبحانه وتعالى ويعلمها فإذا انتهت المدة التي قدرها الله لهم أخرجوا من النار وصاروا إلى نهر يقال له: نهر الحياة فينبتون فيه كما تنبت الحبة في حميل السيل فإذا تم خلقهم أذن لهم بدخول الجنة فضلًا من الله سبحانه وتعالى.\nنسأل الله للجميع التوفيق والهداية والعلم النافع. نعم.\nالمقدم: جزاكم الله خيراً. إذاً علينا أن نصدق بما جاء في القرآن الكريم وبما جاءت به السنة الكريمة فيما يخص نعيم القبر وفيما يخص عذابه، وعلينا أن نبتعد عن الشكوك والأوهام فيما يخطر ببال الإنسان حول ذلك؟\nالشيخ: نعم، كل ما عرض للإنسان من شكوك أو أوهام يعرضها على القرآن والسنة حتى تزيل ذلك فما في الكتاب والسنة هو المعين الصافي، هو الذي يزيل الشكوك والأوهام ويجعل المؤمن في راحة وطمأنينة مرتاحاً لما قاله الله ورسوله وإن كان لا يفهم ذلك أو لم يعرف الحكمة في ذلك، فالله أحكم وأعلم، إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ [الأنعام:83] لا يعذب إلا لحكمة ولا ينعم إلا لحكمة ولا يعطي إلا لحكمة ولا يمنع إلا لحكمة هو الحكيم سبحانه وتعالى، هو الحكيم العليم بكل شيء سبحانه وتعالى.\nالمقدم: بارك الله فيكم. سماحة الشيخ لعل ما توصل إليه العلم الحديث في الوقت الحاضر يقرب لبعض الإخوان حقيقة تلك المسائل ولاسيما فيما يتعلق ....\nالشيخ: قد يستعان به في بعض الشيء. نعم.\nالمقدم: فيما يتعلق بالتصوير فيما يتعلق بالتسجيل فيما يتعلق بتلك الأمور..\nالشيخ: كل هذه الأشياء التي تحدثت فيها عبرة بعض الناس كانوا يتساءلون ويقولون: كيف ينادي أصحاب الجنة أصحاب النار وأصحاب الجنة في أعلى عليين والنار في أسفل سافلين، بينهم التباعد العظيم فأراهم الله هذه العجائب الآن، هذا المذياع الذي من أقصى الدنيا إلى أقصى الدنيا يسمعون منه الأخبار ويريهم الله العبرة، هذا المذياع وهذا الرائي الآن الذي يسمعه الناس من بعيد وهذا الهاتف التلفون يتخاطبون به من بعد إلى بعد، هذه آية وعبرة تدلهم على صحة ما أخبر به الرسل من كون أهل الجنة ينادون أهل النار ويسمعون عواءهم وشرهم إذا أرادوا ذلك، كل هذا من آيات الله. نعم.\nالمقدم: بارك الله فيكم. تسجيل خطوات الإنسان وتسجيل صوته سماحة الشيخ لعل لهذا أيضاً تأثير على حفظ الأعمال وإتقانها وأن كل شيء مقيد ومحفوظ؟\nالشيخ: يقال كذا رؤيته في التلفاز وغيره أهل الجنة يرون أهل النار فَاطَّلَعَ فَرَآهُ فِي سَوَاءِ الْجَحِيمِ [الصافات:55] مع البعد العظيم الله أقدره أن يرى أهل النار، هذه من آيات الله كما الآن يرى الإنسان يتكلم في محل بعيد تنقله الأقمار الصناعية ويراها الآن في مكان آخر. نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: سبحان الله! ...... هذه آيات من آيات الله سَنُرِيهِمْ آيَاتِنَا فِي الآفَاقِ وَفِي أَنْفُسِهِمْ حَتَّى يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ [فصلت:53]، فهو على كل شيء قدير سبحانه وبكل شيء عليم يري عباده العبر ويوضح لهم الآيات لعلهم يعقلون لعلهم يفهمون لإقامة الحجة وقطع المعذرة. نعم.\nالمقدم: كأني بسماحة الشيخ يدعو إلى تأمل مثل هذه الأشياء وهي تقرب تلك الصور؟\nالشيخ: لا شك أنها تقرب وتعين على فهم الكتاب والسنة، تعين على فهم الكتاب والسنة، فيما أشكل من هذه الأمور. نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: الله المستعان.","link":"https://binbaz.org.sa/fatwas/6981/هل-حياة-الموتى-في-قبورهم-كحياتهم-في-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_136/13603.mp3","categories":["عذاب القبر ونعيمه "]},{"id":8976,"question":"ألاحظ سماحة الشيخ بعض العامة إذا رأى شجر نبت على قبر ما يصف صاحب القبر بأنه كان على صفات مقدارها كذا وكذا، هل لنبوت الأشجار على القبور شيء من العذاب؟","title":"لا علاقة لنمو الأشجار على القبور بالصلاح والفساد","answer":"الجواب: هذا لا صل له؛ لا أصل لهذا وليس للنبات شيء؛ لأن النبات عند نزول الأمطار قد يكون التراب الذي على القبر تراب مناسب، تراب حرث فتنبت فيه الأشجار والعشب ولا يدل على صلاح ولا فساد بل هذا من أسباب طبيعة الأرض التي جعل الله فيها ما جعل من أصول النبات وبذور النبات.\nفإذا كانت الأرض فيها بذور نبتت بإذن الله، وإن كانت خالية لم ينبت عليها شيء.\nفالحاصل أنه ينبت على قبر الطيب وعلى قبر الخبيث ليس دليلاً على أنه طيب بل هذا من ظنون العامة أو من أهل العقائد والطرق المنحرفة.","link":"https://binbaz.org.sa/fatwas/7134/لا-علاقة-لنمو-الاشجار-على-القبور-بالصلاح-والفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14609.mp3","categories":["عذاب القبر ونعيمه "]},{"id":9983,"question":"أولى رسائل هذا الحلقة رسالة المستمع: محمد محمد إبراهيم سعد من محافظة الدقهلية في جمهورية مصر العربية، أخونا محمد له جمع من الأسئلة، في أحد أسئلته يسأل ويقول: هل صحيح أن الميت يعذب ببكاء أهله عليه، وإذا كان هذا صحيح ما ذنب الميت في هذا العذاب، علمًا بأن هذا ليس من عمله؟","title":"عذاب الميت في قبره ببكاء أهله عليه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: إن الميت يعذب في قبره بما يناح عليه، وفي اللفظ الآخر: أن الميت يعذب في قبره بنياحة أهله عليه، ونحن علينا السمع والطاعة والامتثال، والله سبحانه لا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ [الأنبياء:23].\nوالبكاء الذي في الحديث يعني: النياحة، في بعض الروايات: (ببكاء)، والمراد يعني: النياحة، والبكاء الذي يعذب به النياحة، يعني: رفع الصوت، أما دمع العين فلا حرج في ذلك.\nولعل من الحكمة في ذلك أن يجتهد في توصية أهله وأقاربه أن لا ينوحوا، وأن يحذرهم في حياته من ذلك؛ لئلا يعذب في قبره بأسبابهم، ولعل العذاب الذي يكون في قبره بأسبابهم عذاب خاص لا نعلم كيفيته، وأما قوله جل وعلا: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] فهذا عام وهذا خاص، والخاص لا يعارض العام بل يخصص منه، وله نظائر في الشريعة يأتي العام ويأتي الخاص، فلا يستغرب ذلك. وعرفت أن من الحكمة والله أعلم في ذلك: أن علمه بأنه يعذب بالنياحة يدعوه إلى أن يوصيهم بالترك ويحذرهم من هذه المعصية الجاهلية، وهم أيضًا كذلك إذا علموا يكون هذا أدعى إلى صبرهم وعدم جزعهم، وإلى تركهم النياحة رحمة بميتهم، وحذرًا من تعذيبه بأسبابهم، نسأل الله لنا ولهم الهداية والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8144/عذاب-الميت-في-قبره-ببكاء-اهله-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33101.mp3","categories":["عذاب القبر ونعيمه "]},{"id":10946,"question":"يسأل سؤالًا آخر حول الموضوع تقريبًا، يقول: هل الشخص الميت يراك أثناء زيارتك إلى قبره، أم لا؟ وهل الزيارة يوم الإثنين أو الخميس؟ وهل تجوز في باقي الأيام؟","title":"هل الموتى يرون من زارهم وقت الزيارة؟","answer":"الجواب:  الزيارة في كل وقت، جميع الأوقات ليس لها وقت معين، في جميع أيام الأسبوع في الليل والنهار، متى تيسر له الزيارة زار. أما كون الميت يراه فلا أصل لهذا، الميت انتهى أمره، وحيل بينه وبين ذلك، وروحه إما في الجنة إن كان مؤمنًا، وإما في النار إن كان كافرًا، والعاصي على خطر من ذلك، وليس هناك دليل على أن الميت يرى زائره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9125/هل-الموتى-يرون-من-زارهم-وقت-الزيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36309.mp3","categories":["زيارة القبور","عذاب القبر ونعيمه "]},{"id":11075,"question":"هذا سائل للبرنامج رمز لاسمه بـ (أ. أ. أ) يقول: عندما يموت الإنسان وعند دفنه هل يعذب مدى موته حتى القيامة، وذلك إذا كان مسيئًا فعلًا وقولًا وعملًا، أم لفترة حسب الأعمال، أو حسب أعماله، نرجو منكم التوجيه؟ جزاكم الله خيرًا.","title":"حقيقة تعذيب الكفرة والعصاة في البرزخ","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد دلت الأحاديث الصحيحة عن رسول الله ﷺ أن العبد إذا وضع في قبره أتاه الملكان يسألانه: عن ربه ودينه ونبيه؟ فإن ثبته الله، وأجاب الجواب الصحيح فتح له باب إلى الجنة يأتيه من نعيمها وطيبها، ويفتح له باب إلى النار يقال: هذا مقعدك لو كفرت بالله، قد أبدلك الله به هذا المقعد من الجنة، يراهما جميعًا، والكافر بعكس ذلك، يفتح له باب إلى النار يأتيه من عذابها وشرها وسمومها، وباب إلى الجنة يقال: هذا مقعدك لو هداك الله، ولكنك كفرت بالله فحرمت هذا المقعد. فظاهر السنة والكتاب أن المهتدي ينعم، والكافر يعذب، لكن كيف يعذب؟ وكيف يستمر العذاب؟ هذا إلى الله . وهكذا كيفية النعيم إلى الله، ليس عند المؤمن إلا ما جاءت به الأحاديث، يؤمن بما جاءت به الأحاديث، أما كيفية النعيم واستمراره، وكيفية العذاب واستمراره هذا إلى الله سبحانه، يقول الله في آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ [غافر:46] دلت الآية على أنهم يعرضون غدوًا وعشيًا، ليس دائمًا. فالمقصود أن التعذيب والنعيم هذا يرجع إلى الله، التفصيل والكيفية إليه  لكن نعلم أن المؤمن منعم في قبره والكافر معذب في قبره، وكيف النعيم؟ وكيف العذاب؟ هذا إلى الله  ليس عندنا إلا ما جاء به النص: أنه يفتح باب إلى الجنة للمؤمن، ويأتيه من نعيمها وطيبها، والكافر يفتح له باب إلى النار -نسأل الله العافية- وفي الصحيحين من حديث ابن عباس: أن النبي ﷺ أطلعه الله على قبرين قال: إنهما ليعذبان ثم قال: وما يعذبان في كبير ثم قال: بلى، أما أحدهما فكان لا يستتر من البول يعني: لا يتنزه من البول وأما الآخر فكان يمشي بالنميمة فأخبر أنهما يعذبان في هذين الأمرين، أما كيفية العذاب فلم يبين لنا. أما العاصي فهو ذو الشائبتين، وليس في السنة والكتاب ما يوضح فيما نعلم كيفية نعيمه، ولا كيفية عذابه، هو على خطر، الذي يموت على معاصي لم يتب منها كالزنا، أو الخمر، أو العقوق، هو على خطر من العذاب، لكن لا يعلم كيفية ذلك إلا الله  لكن ليس من جنس الكافر، وليس من جنس المؤمن السليم، بل هو بينهما، وفي الآخرة كذلك قد يعذب وقد يعفو الله عنه ويدخل الجنة، وقد يدخل النار، لكن لا يخلد فيها، يعذب بقدر معاصيه، ثم يخرجه الله من النار إلى الجنة، فحاله بين الحالين، هو الظالم لنفسه، لكن مصيره إلى الجنة منتهاه إلى الجنة والسلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9253/حقيقة-تعذيب-الكفرة-والعصاة-في-البرزخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28901.mp3","categories":["عذاب القبر ونعيمه "]},{"id":11200,"question":"إذا توفي مسلم في يوم الجمعة أو في شهر رمضان، هل ينجو من عذاب القبر، وهذا سؤال من المستمع سليمان أحمد من السودان؟","title":"هل من مات يوم الجمعة أو رمضان ينجو من عذاب القبر؟","answer":"الجواب:  ليس هناك دليل، الأحاديث التي وردت في الجمعة أحاديث كلها غير صحيحة، لكن يرجى له إذا مات على أثر صوم وأثر عبادة يرجى له الخير، وأما أنه إذا مات في رمضان أو مات في الجمعة، ينجو من العذاب، لا، بل هذا إلى الله ، إن مات على استقامة فله الجنة والكرامة، وإن مات على معاصي فهو على خطر، ويدعى له بالمغفرة والرحمة. نعم.","link":"https://binbaz.org.sa/fatwas/9379/هل-من-مات-يوم-الجمعة-او-رمضان-ينجو-من-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37223.mp3","categories":["عذاب القبر ونعيمه "]},{"id":11208,"question":"هذا السائل الذي لم يذكر الاسم في هذه الرسالة يقول: إذا مات المسلم وأدخل في القبر فهل ترد عليه روحه، وهل يأتيه الإخوان أو إخوانه الموتى ويسألونه عن أحوال أهليهم وذويهم، أفيدونا بالتفصيل نفع الله بعلمكم؟","title":"ما صحة أن الميت يجتمع إليه الموتى من المؤمنين؟","answer":"الجواب:  إذا وضع الميت في قبره ثبت في الأحاديث الصحيحة أنها ترد عليه روحه ويأتيه ملكان يسألانه عن ربه وعن دينه وعن نبيه، هذا ثابت، أما اجتماعه بأهله فلا أصل له في الأحاديث الصحيحة، إنما الثابت أنه ترد عليه روحه حتى يسأل، وهي حياة برزخية ليست من جنس حياة أهل الدنيا بل هي حياة خاصة يعقل بها ويفهم ما يسأل عنه، فيثبت الله أهل الإيمان ويضل الله الظالمين. نعم.","link":"https://binbaz.org.sa/fatwas/9389/ما-صحة-ان-الميت-يجتمع-اليه-الموتى-من-المومنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29108.mp3","categories":["عذاب القبر ونعيمه "]},{"id":11613,"question":"يقول: أيضًا يوجد أناس لا يصدقون بعذاب القبر؛ وذلك لأنه لم يذكر في القرآن الكريم، فوجهونا، جزاكم الله خيرًا.","title":"حكم من ينكر عذاب القبر لعدم ذكره في القرآن","answer":"الجواب:  عذاب القبر حق، وقد تواترت به النصوص عن النبي ﷺ، وأجمع عليه المسلمون، ودل عليه القرآن الكريم في قوله تعالى: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا هذا معناه في البرزخ وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ [غافر:46] فقوله: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا [غافر:46] هذا في البرزخ، نسأل الله العافية. فالمقصود: أن من أنكر عذاب القبر يستتاب، فإن تاب؛ وإلا قتل كافرًا، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9795/حكم-من-ينكر-عذاب-القبر-لعدم-ذكره-في-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38806.mp3","categories":["عذاب القبر ونعيمه "]},{"id":11659,"question":"يقول: قرأت وسمعت عن البرزخ عرفوه لنا، جزاكم الله خيرًا.","title":"البرزخ حقيقته ووقته","answer":"الجواب:  البرزخ: هو ما بين وضع الإنسان في قبره إلى قيام الساعة هذا البرزخ، ما بين وضع الإنسان في قبره إلى أن تقوم الساعة هذا هو البرزخ، فالذين وضعوا في قبورهم في عهد آدم وبعده، هم في البرزخ إلى الآن، إلى يوم القيامة، وهكذا من بعدهم، وهكذا من بعدهم، وهكذا في يومنا من مات الآن صار إلى البرزخ، ويستمر في ذلك إلى أن تقوم الساعة. فالبرزخ ما بين موتك، وما بين قيام الساعة، هذا البرزخ، وهكذا ما بين موت الناس إذا قامت القيامة، ومات الناس هم في برزخ حتى يبعثوا، فإذا بعثوا انتهوا من البرزخ، وتوجهوا للحساب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9842/البرزخ-حقيقته-ووقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29811.mp3","categories":["عذاب القبر ونعيمه "]},{"id":12894,"question":"يقول: يتبادر إلى أذهان كثير من الناس، أن الميت إذا مات، ولم يدفن في القبر؛ فإنه ينجو من عذاب القبر، فبماذا تنصحون من يفكر مثل هذا التفكير، جزاكم الله خيرًا؟","title":"هل إذا مات ولم يدفن نجا من عذاب القبر؟","answer":"الجواب:  الميت يسأل، سواء كان في قبره، أو في أي مكان، أو في الصحراء، أو في البحار، أو في بطون السباع، هو مسؤول، والمسؤولية للروح، والروح سالمة، فهو يسأل، ويعذب إن كان شقيًا، أو ينعم إن كان تقيًا، تنعم روحه في الجنة، أو تعذب في النار، وللجسد نصيبه، الجسد الذي بقي منه عظام، أو جلد، ما بقي من الجسد له نصيبه من النعيم والعذاب على الكيفية التي يعلمها الله ، ولكن المعظم على الروح في البرزخ، ويوم القيامة يجتمع العذاب على البدن والروح، وهكذا النعيم، إما في الجنة كأهل الإيمان والتقوى، وإما في النار كأهل الكفر بالله. فالحاصل: أن النعيم، والعذاب للروح والجسد جميعًا، لكن في البرزخ معظمه على الروح والجسد يناله نصيبه، وإن كان في البحار، وإن كان في بطون السباع، وإن كان في أي مكان، فالروح لها نصيبها من النعيم والعذاب مطلقًا، ولكن في البرزخ الروح لها الحظ الأوفر من النعيم والعذاب، ويوم القيامة يتوفر النعيم لأهل الإيمان للروح والجسد جميعًا، ولأهل الشقاء يتوفر العذاب للروح والجسد جميعًا، نسأل الله العافية. وهكذا العاصي له نصيبه إن دخل النار، فالعذاب للروح والجسد، وإن أنجاه الله؛ فالنعيم للروح والجسد، وهكذا بعد خروجه من النار، فإن العصاة كثير منهم يدخلون النار بمعاصيهم، ويطهرون، فإذا طهروا من سيئاتهم بالعذاب؛ أخرجهم الله إلى الجنة، فهم يعذبون روحًا وجسدًا، وينعمون روحًا وجسدًا، ولا يخلد في النار إلا الكفرة، لا يخلد في النار الخلود النهائي الذي لا نهاية له إلا الكفرة. قد يخلد العاصي كالزاني والقاتل، قد يخلد خلودًا له نهاية، خلودًا طويلًا، يعني: طويلًا، يعني: مدة طويلة، لكن له نهاية، كما قال الله سبحانه في الزاني القاتل: وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69] وقال في القاتل: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ [النساء:93] الآية، فهذا خلود له نهاية، ليس مثل خلود الكفار، أما خلود الكفار -نعوذ بالله- فإنه لا ينتهي، كما قال الله في حقهم: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167] وقال في حقهم سبحانه: لا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا كَذَلِكَ نَجْزِي كُلَّ كَفُورٍ [فاطر:36] نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11109/هل-اذا-مات-ولم-يدفن-نجا-من-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46709.mp3","categories":["عذاب القبر ونعيمه "]},{"id":12972,"question":"هذه سائلة تقول: هل يعرف الميت أخبارنا؟ وكيف ذلك إذا كان يعرفها؟ وهل يسمعنا إذا ذهبنا إلى مكان القبر وكلمناه؟","title":"صحة سماع الميت لأهل الدنيا","answer":"الجواب:  هذا فيه تفصيل: أما كونه يسمع أخبارهم على الإطلاق فلا، يقول الله سبحانه: إِنَّكَ لا تُسْمِعُ الْمَوْتَى [النمل:80] ويقول سبحانه: وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ [فاطر:22] ويقول ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له ومن ذلك السماع ينقطع إلا ما جاء به النص يعني: ما هو مستثنى، مثل قوله ﷺ في الميت إذا انصرفوا عنه: إنه ليسمع قرع نعالهم هذا جاء به النص كونه سمع، وكونه يسمع في قبره الملك إذا سأله: من ربك؟ ما دينك؟ هذا جاء به النص. أما كونه يسمع أخبارهم في بيوتهم لا، لا دليل عليه، ولا يسمع، ولا يعلم أخبارهم، ولا يسمعها. أما من جاء يسلم عليه هذا فيه خلاف بين أهل العلم، وفيه أخبار جاءت فيها ضعف، أنه إذا سلم عليه من يعرفه؛ رد الله عليه روحه حتى يرد عليه السلام هذا قول له قوة، ومن هذا الحديث الصحيح قوله ﷺ: ما من أحد يسلم علي إلا رد الله عليَّ روحي حتى أرد عليه السلام.  هذا قول قوي، إذا سلم عليه من يعرفه في الدنيا، كونه ترد عليه روحه حتى يرد السلام قول قوي، ولكن الأحاديث في صحتها نظر فيها ضعف، فيقال: يمكن هذا، الله أعلم، يمكن إن صحت الأخبار؛ لأن الأخبار فيها ضعف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11189/صحة-سماع-الميت-لاهل-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50305.mp3","categories":["عذاب القبر ونعيمه "]},{"id":13107,"question":"تقول السائلة سماحة الشيخ: ما الأسباب المنجية من عذاب القبر، والتي تجادل عن صاحبها؟ هل المريض بالسرطان في بطنه يعتبر شهيدًا؛ لأن المبطون شهيد، وجهونا بذلك مأجورين؟","title":"أسباب السلامة من عذاب القبر وحكم المتوفى بمرض السرطان","answer":"الجواب:  أسباب السلامة في القبر طاعة الله ورسوله، الاستقامة على دين الله، والحذر من المعاصي، هذه أسباب السلامة في القبر، والمريض بالسرطان، أو غيره هذا على خير عظيم، يرجى له خير عظيم، المرض كفارة للسيئات، فإذا أصاب الإنسان مرض؛ فهو كفارة، ما أصاب العبد من المرض والهم والغم، حتى الشوكة؛ يكفر الله بها من خطاياه. وأسباب الشهادة كثيرة: المطعون الذي يصاب بالطاعون، والمبطون الذي يصاب بمرض البطن، والمجذوم، وكذلك صاحب الهدم، وصاحب الغرق، والشهيد في سبيل الله، كل هذه أنواع من الشهادة، وكل إنسان يصيبه مرض، أو شيء من الأذى هو كفارة لخطاياه حتى الشوكة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11324/اسباب-السلامة-من-عذاب-القبر-وحكم-المتوفى-بمرض-السرطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50815.mp3","categories":["عذاب القبر ونعيمه "]},{"id":13567,"question":"يقول هذا السائل من اليمن: البعض من الناس قد يموتون بسبب تهدم عمارة عليهم، وبالتالي يصعب نقلهم، ودفنهم في قبور المسلمين، فهل يعذب هؤلاء بعذاب القبر وهم في أماكنهم، أم ماذا؟ جزاكم الله خيرًا.","title":"إذا لم يدفن الميت هل يعذب عذاب القبر؟","answer":"الجواب: كل ميت يمتحن في أي مكان في البر، أو في البحر، أو في هدم، أو في غيره، يرسل إليه الملك فيمتحنه، فإن كان سعيدًا؛ حصل له النعيم، ونقلت روحه إلى الجنة، وإن كان شقيًا حصل له العذاب، وصارت روحه إلى النار -نسأل الله العافية- فالمؤمن على خير مهما كان في هدم، أو في بحر، أو في أي مكان على خير عظيم، ويصل إليه النعيم في محله، وروحه تنقل إلى دار الكرامة، إلى الجنة كما جاء في الحديث الصحيح: أن أرواح المؤمنين طائر يسرح في الجنة، وأرواح الشهداء في أجواف طير خضر تسرح في الجنة حيث شاءت، ثم تأوي إلى قناديل معلقة تحت العرش. والمؤمن يرى مقعده من الجنة، ومقعده من النار، فيقال: هذا مقعدك من الجنة...... ويأتيه من ريحها ونعيمها، وهذا مقعدك من النار، كفاك الله إياه، ومنعك منه بسبب طاعتك وتوحيدك، والكافر ضد ذلك. فالمقصود: أن الميت في أي مكان في هدم، أو في غيره يناله ما وعده الله به من خير وشر. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11905/اذا-لم-يدفن-الميت-هل-يعذب-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52216.mp3","categories":["عذاب القبر ونعيمه "]},{"id":14905,"question":"هل صحيح أن روح الميت تظلله حتى يدخل إلى قبره فتدخل معه؟ وهل صحيح أن الميت يحس بالذين يغسلونه والذين يمشون في جنازته؟","title":"هل روح الميت تظلله؟ وهل يحس بمن يغسله ويشيعه؟","answer":"الجواب: لا أعلم لهذا أصلًا، أقول: لا أعلم لهذا أصلًا، الروح روح المؤمن إذا قبضت ترفع إلى السماء إلى الله، ثم يأمر بإرجاعها إلى جسدها، حتى يسأل في القبر: من ربه؟ ما دينه؟ من نبيه؟ والكافر إذا ارتفعت روحه غلقت عنها أبواب السماء، بل هذا يدل على أن الروح تغادر جسد الإنسان عند الموت، لا تظلل عليه، بل تغادر، لكن روح المؤمن ترفع إلى السماء، فوق السماء السابعة، ويقول الله -جل وعلا-: ارجعي من حيث جئت يردها إلى جسدها، حتى يسأل عن ربه، وعن دينه، وعن نبيه.  والكافر تغلق عنها أبواب السماء، وتطرح طرحًا، نسأل الله السلامة، نعم. المقدم: نسأل الله العفو والعافية، جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13404/هل-روح-الميت-تظلله-وهل-يحس-بمن-يغسله-ويشيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56206.mp3","categories":["عذاب القبر ونعيمه "]},{"id":15163,"question":"السائل يقول: بأنه سمع بأن أغلب عذاب أمة محمد ﷺ في قبرها؟ فهل هذا الكلام صحيح يا سماحة الشيخ؟","title":"هل أغلب عذاب أمة محمد ﷺ في قبرها؟","answer":"الجواب: يقول النبي ﷺ: استنزهوا من البول، فإن عامة عذاب القبر منه ويقول ﷺ: إنه رأى شخصين يعذبان في قبورهما، أحدهما: كان لا يستتر من البول يعني: لا يتنزه من البول، فالواجب على المسلم والمسلمة الحذر من البول، والتنزه منه، فإذا استنجى من البول يعتني، وإذا أصاب فخذه شيء، أو ثوبه غسله، هذا هو الواجب على الرجل والمرأة عند البول، أن يحترز من البول، ويحرص ألا يصيب ثيابه، ولا بدنه شيء، نعم.","link":"https://binbaz.org.sa/fatwas/13655/هل-اغلب-عذاب-امة-محمد-ﷺ-في-قبرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56416.mp3","categories":["عذاب القبر ونعيمه "]},{"id":15306,"question":"سماحة الشيخ، هذا سائل يقول: هل الذي ينعم في قبره يستمر نعيمه إلى دخول الجنة، أم أنه من الممكن أن يعذب يوم القيامة؟وجهونا في ضوء ذلك.","title":"هل يستمر النعيم لمن ينعم في قبره حتى يدخل الجنة؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد ثبتت الأحاديث عن رسول الله ﷺ دالة على أن الميت يمتحن في قبره، فيسأل عن ربه، وعن دينه، وعن نبيه، فإن نجح وأجاب جوابًا صحيحًا فتح له باب إلى الجنة يأتيه من نعيمها وريحها وطيبها، وصار قبره روضة عليه من رياض الجنة، ويستمر هذا النعيم إلى أن يبعث يوم القيامة، ومن قبره إلى الجنة. أما إذا لم ينجح في الاختبار كالذي يقول: هاه هاه لا أدري، سمعت الناس يقولون شيئًا فقلته، فهذا يعذب في قبره والعياذ بالله، ثم بعد ذلك هو تحت مشيئة الله، إن كان من أهل المعاصي تحت مشيئة الله، وإن كان من أهل الكفر بالله نقل إلى النار، نسأل الله العافية، وإن كان من أهل المعاصي فهو تحت المشيئة، كما قال الله تعالى: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ[النساء:48] نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13803/هل-يستمر-النعيم-لمن-ينعم-في-قبره-حتى-يدخل-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56601.mp3","categories":["عذاب القبر ونعيمه "]},{"id":15650,"question":"سؤاله الثاني يقول: رأيت والدي في منتصف الليل يصلي صلاة الليل ثمان ركعات، فسألته عن فائدة الصلاة في الليل، فقال: إن الإنسان الذي يصلي في الليل لا تأكل الأرض جسده بعد وفاته، فهل هذا صحيح؟ وهل يبقى الإنسان في قبره إذا كان يصلي صلاة الليل والناس نيام؟ وهل الروح تبقى في الجسد بعد الوفاة أم تصعد إلى خالقها؟","title":"ما صحة عدم أكل الأرض جسد من يقوم الليل؟","answer":"الجواب:  صلاة الليل قربة عظيمة، وسنة مؤكدة، قال الله -جل وعلا- في وصف عباد الرحمن: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا[الفرقان:64] وقال سبحانه في وصف المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ[الذاريات:18] قال الله لنبيه -عليه الصلاة والسلام-: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا ۝ نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا ۝ أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا[المزمل:4] وقال سبحانه: تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ[السجدة:16] والآيات في هذا كثيرة تدل على فضل قيام الليل، والنبي ﷺ كان يتهجد بالليل كثيرًا -عليه الصلاة والسلام-، ويقول: أيها الناس، أفشوا السلام، وأطعموا الطعام، وصلوا الأرحام، وصلوا بالليل والناس نيام، تدخلوا الجنة بسلام التهجد بالليل من أفضل القربات، ومن أعظم الطاعات، وكان ﷺ في الأغلب يصلي إحدى عشرة ركعة، يسلم من كل ثنتين، ويوتر بواحدة -عليه الصلاة والسلام-، وربما أوتر بأقل من هذا، ربما أوتر بتسع، وربما أوتر بسبع، وربما أوتر بخمس، ولكن الأغلب أنه كان يصلي إحدى عشرة، وربما صلى ثلاث عشرة -عليه الصلاة والسلام- في الليل، يطيل في قراءته وركوعه وسجوده -عليه الصلاة والسلام-. أما كونه لا تأكل الأرض جسمه إذا كان يصلي من الليل فهذا لا أعلم له أصلًا، لا أعلم في الأدلة الشرعية ما يدل على ذلك. وأما الروح -روح المؤمن- فإنها تعلق في شجر الجنة، تكون في الجنة.....، الله الجنة -جل وعلا-، وتعلق في أشجارها كالطائر، شبه طائر تعلق في أشجار الجنة وثمارها، كما صح به الخبر عن رسول الله ﷺ أنه قال: روح المؤمن طائر، يعلق في شجر الجنة. وأما أرواح الشهداء فأخبر النبي ﷺ أنها تكون في أجواف طير خضر، تسرح في الجنة حيث شاءت، ثم تعود إلى قناديل معلقة تحت العرش. فأرواح المؤمنين في الجنة مكرمة، لكن أرواح الشهداء لها شأن، ويعيد الله الأرواح إلى أجسادها إذا شاء كما يعيدها عند السؤال، حين يموت الإنسان، ويوضع في قبره يأتيه الملك فيسأله عن ربه وعن دينه وعن نبيه، ويعيد الله له روحه فيسمع السؤال، ويجيب إن كان صالحًا، ويتردد ولا يستطيع الإجابة إذا كان كافرًا أو منافقًا، نسأل الله السلامة. أما أرواح الكفار ففي النار، نسأل الله العافية، أرواحهم في النار، قد قال الله -جل وعلا- في آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ[غافر:46]. واختلف أهل العلم في مستقرها، فقيل: في نفس النار، وقيل: في قبور أصحابها، وقيل في غير ذلك. ولكنها بكل حال معذبة نعوذ بالله، وتعرض على النار ومصيرها إلى النار نسأل الله العافية، نعم. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/14192/ما-صحة-عدم-اكل-الارض-جسد-من-يقوم-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_698/nour_69802.mp3","categories":["الوتر وقيام الليل","عذاب القبر ونعيمه "]},{"id":15747,"question":"هل الميت بعد دخوله القبر، وصعود روحه إلى خالقها، يحس بأهله في الدنيا، وما فعلوه من بعده؟","title":"هل يحس الميت بما يفعل أهله؟","answer":"الجواب: ليس لهذا أصل، إذا مات انقطع علمه بأهل الدنيا، إذا مات انقطع علمه بأهل الدنيا، يقول -جل وعلا-: إِنَّكَ لا تُسْمِعُ الْمَوْتَى [النمل:80] قال تعالى: وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ [فاطر:22].  فالمقصود: أن الميت إذا مات انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له ولا يعلم أحوال الناس بعده، لا أحوال أهله، ولا غيرهم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14334/هل-يحس-الميت-بما-يفعل-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57508.mp3","categories":["عذاب القبر ونعيمه "]},{"id":15925,"question":"من جمهورية مصر العربية هذا السائل يقول بلال عوض: هل الميت بعد دخوله القبر وصعود روحه إلى خالقها، هل يشعر بأهله في الدنيا وما فعلوا من بعده؟","title":"هل يشعر الميت بأحوال أهله من بعده؟","answer":"الجواب: لا يشعر، الميت انقطع عمله، الله -جل وعلا- يقول: وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ [فاطر:22] إِنَّكَ لا تُسْمِعُ الْمَوْتَى [النمل:80] ويقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. فالميت ما بشعر بأحوال أهله، الله المستعان، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14520/هل-يشعر-الميت-باحوال-اهله-من-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57715.mp3","categories":["عذاب القبر ونعيمه "]},{"id":16639,"question":"هل تلتقي الأرواح بعد الموت حتى وإن بعدت المسافات بين الأجساد بوجود أحدهما في مدينة، والآخر في مدينة أخرى، فقد علمنا -كما يقول صاحب السؤال- أن أصحاب المقبرة يستقبلون الميت الطيب، فهل يقتصر الاستقبال على المقبرة التي سوف يدفن فيها، أم لا؟ وقد علم ذلك أيضًا، قد علم ذلك الاستقبال من الرؤى لعدة أشخاص، جزاكم الله خيرًا.","title":"هل تلتقي الأرواح بعد الموت؟","answer":"الجواب: أما من ناحية الأدلة الشرعية فلا أعلم في الباب شيئًا من الآيات، ولا من الأحاديث يدل على تلاقي الأرواح، وأنها تتعارف، وتتلاقى، وتتساءل. أما المرائي فكثيرة، المرائي، رؤيا المؤمنين، المرائي كثيرة في تلاقي الأرواح، واستبشارهم بروح المؤمن، إذا كان المؤمن يستبشر بروح المؤمن، والكفار كذلك يسوءهم ما يحصل لهم من أرواح أخرى تذهب إلى النار، هذه المرائي كثيرة. كذلك مرائي تدل على أن الميت قد يبين لأهله أشياء، قد لم يذكرها لهم، قد يقول: إن علي دينًا لفلان، ثم يسأل ويصدق، قد يقول: تجدون في المحل الفلاني كذا، فيجدونه، بل قد يأتي بأشياء في المرائي يصدقها الواقع، هذا واقع في المرائي. وقد حدثنا بهذا كثير من الثقات، بأنه رأى أباه، أو رأى أخاه، أو رأى فلانًا فقال له: أعطوا فلانًا عني كذا وكذا، أعطوا فلانًا عني كذا وكذا؛ لأنه يطلبني كذا وكذا، فيسألون الشخص، فيقول: نعم، إني أطلبه كذا وكذا، هذا وقع في مرائي كثيرة، وليس هذا ببعيد، بل هو ممكن، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15372/هل-تلتقي-الارواح-بعد-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71702.mp3","categories":["عذاب القبر ونعيمه "]},{"id":16979,"question":"سؤاله الثاني يقول: إن الله -تبارك وتعالى- لم يخبر عن الأموات أنهم أحياء إلا الشهداء، ففي أي حالة تكون أرواح الصالحين الذين لم يموتوا شهداء؟ وهل هناك فرق بينهم في حياة البرزخ؟ جزاكم الله خيرًا.","title":"مصير أرواح المؤمنين والشهداء بعد الموت","answer":"الجواب: الشهداء لشرفهم، وفضل عملهم بين الله -سبحانه- أنهم أحياء عند ربهم يرزقون، حياةً خاصة، حياةً برزخية، وهم أموات، هم أموات، قد حكم فيهم بأحكام الموتى، لكن أرواحهم في نعيم الجنة، في أجواف طير خضر تسرح في الجنة حيث شاءت، ثم تأوي إلى قناديل معلقة تحت العرش، كما أخبر به النبي -عليه الصلاة والسلام- فهذا شرف لهم، وحث لهم على الجهاد في سبيل الله، وهكذا أرواح المؤمنين عند الله أيضًا في الجنة، حية عند الله في الجنة، لكنهم دون الشهداء، جاء في الحديث الصحيح: أن روح المؤمن طائر يعلق في شجر الجنة روح المؤمن يجعلها الله طائرًا يعلق في شجر الجنة، ويأكل من ثمارها، حتى يعيدها الله إلى جسده، وهذا فضل عظيم. وهكذا أرواح الكفار حية تعذب في البرزخ، وفي النار، في البرزخ مع الجسد، الجسد في الأرض وهي تعذب في النار، والجسد والروح يوم القيامة يعذبان في النار أيضًا، نسأل الله العافية. فالمؤمنون ينعمون في البرزخ، وفي الجنة أرواحًا، وأجسادًا، والكفار يعذبون في البرزخ، وفي النار أرواحًا وأجسادًا، وللروح نصيبها، وللجسد نصيبه، ولو لم يبق منه إلا القليل. فالواجب على كل مسلم أن يحذر، وأن يعد العدة للقاء ربه، وأن يبتعد عن كل ما حرم الله عليه، والعاصي على خطر إذا مات على المعاصي، على خطر من العذاب في قبره، ومن عذاب النار، وإن كان لا يخلد فيها لو دخلها، لكنه على خطر، فالواجب الحذر من المعاصي كلها؛ لعل الله ينجيه من شرها. قد ثبت عنه ﷺ أنه رأى شخصين يعذبان في قبورهما، أحدهما يعذب بالنميمة .. كان يمشي بالنميمة، وهي معصية كبيرة من كبائر الذنوب، والثاني يعذب بأنه ما كان يستنزه من البول، ما كان يتحرز من البول، هذا يفيد الحذر من المعاصي، ويفيد الحذر من التساهل بالبول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15778/مصير-ارواح-المومنين-والشهداء-بعد-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82906.mp3","categories":["عذاب القبر ونعيمه "]},{"id":16995,"question":"سؤاله الثاني يقول: إن الله -تبارك وتعالى- لم يخبر عن الأموات أنهم أحياء إلا الشهداء، ففي أي حالة تكون أرواح الصالحين الذين لم يموتوا شهداء؟ وهل هناك فرق بينهم في حياة البرزخ؟ جزاكم الله خيرًا.","title":"مصير أرواح المؤمنين والشهداء بعد الموت","answer":"الجواب: الشهداء لشرفهم، وفضل عملهم بين الله -سبحانه- أنهم أحياء عند ربهم يرزقون، حياةً خاصة، حياةً برزخية، وهم أموات، هم أموات، قد حكم فيهم بأحكام الموتى، لكن أرواحهم في نعيم الجنة، في أجواف طير خضر تسرح في الجنة حيث شاءت، ثم تأوي إلى قناديل معلقة تحت العرش، كما أخبر به النبي -عليه الصلاة والسلام- فهذا شرف لهم، وحث لهم على الجهاد في سبيل الله، وهكذا أرواح المؤمنين عند الله أيضًا في الجنة، حية عند الله في الجنة، لكنهم دون الشهداء، جاء في الحديث الصحيح: أن روح المؤمن طائر يعلق في شجر الجنة روح المؤمن يجعلها الله طائرًا يعلق في شجر الجنة، ويأكل من ثمارها، حتى يعيدها الله إلى جسده، وهذا فضل عظيم. وهكذا أرواح الكفار حية تعذب في البرزخ، وفي النار، في البرزخ مع الجسد، الجسد في الأرض وهي تعذب في النار، والجسد والروح يوم القيامة يعذبان في النار أيضًا، نسأل الله العافية. فالمؤمنون ينعمون في البرزخ، وفي الجنة أرواحًا، وأجسادًا، والكفار يعذبون في البرزخ، وفي النار أرواحًا وأجسادًا، وللروح نصيبها، وللجسد نصيبه، ولو لم يبق منه إلا القليل. فالواجب على كل مسلم أن يحذر، وأن يعد العدة للقاء ربه، وأن يبتعد عن كل ما حرم الله عليه، والعاصي على خطر إذا مات على المعاصي، على خطر من العذاب في قبره، ومن عذاب النار، وإن كان لا يخلد فيها لو دخلها، لكنه على خطر، فالواجب الحذر من المعاصي كلها؛ لعل الله ينجيه من شرها. قد ثبت عنه ﷺ أنه رأى شخصين يعذبان في قبورهما، أحدهما يعذب بالنميمة .. كان يمشي بالنميمة، وهي معصية كبيرة من كبائر الذنوب، والثاني يعذب بأنه ما كان يستنزه من البول، ما كان يتحرز من البول، هذا يفيد الحذر من المعاصي، ويفيد الحذر من التساهل بالبول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15778/مصير-ارواح-المومنين-والشهداء-بعد-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82906.mp3","categories":["عذاب القبر ونعيمه "]},{"id":17076,"question":"السائل يقول في هذه الرسالة سماحة الشيخ: ما هي الوسيلة للنجاة من عذاب القبر؟","title":"كيفية النجاة من عذاب القبر","answer":"الجواب: طاعة الله ورسوله، الاستقامة على دين الله، من استقام على دين الله؛ وقاه الله عذاب القبر، إذا استقام على دين الله، وحفظ جوارحه من محارم الله؛ وقاه الله عذاب القبر. نعم.","link":"https://binbaz.org.sa/fatwas/15883/كيفية-النجاة-من-عذاب-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58816.mp3","categories":["الرقائق","عذاب القبر ونعيمه "]},{"id":17537,"question":"هل يسأل الشهيد والطفل؟","title":"هل يسأل الشهداء والأطفال في القبور؟","answer":"الجواب: ظاهر الأحاديث أنه يسأل المكلفون، أما الطفل ما عليه شيء، ظاهر الأحاديث أن الميت المكلف يسأل عن ربه، وعن دينه، وعن نبيه، أما الطفل فلا أعلم في هذا ما يدل على أنه يسأل؛ لأن الأطفال بإجماع أهل السنة من أهل الجنة، أطفال المسلمين من أهل الجنة. نعم.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16463/هل-يسال-الشهداء-والاطفال-في-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77512.mp3","categories":["عذاب القبر ونعيمه "]},{"id":17588,"question":"يقول: أعلم أن الأرض لا تأكل أجساد الأنبياء، فهل ينطبق ذلك على أولياء الله الصالحين؟ وإن كان كذلك فهل هناك أحد حصل له شيء من هذا؟","title":"هل تأكل الأرض أجساد الأولياء؟","answer":"الجواب: الأحاديث جاءت في أجسام الأنبياء عليهم الصلاة والسلام، يقول ﷺ: إن الله حرم على الأرض أن تأكل أجساد الأنبياء، أما غيرهم فليس بلازم قد تأكل أجسامهم وقد لا تأكل، وقد شاهد الناس في كثير من البلدان عند بعض الأسباب أجسامًا لم تأكلها الأرض ممن يظن فيهم الصلاح، ولكن لا يدرى هل تأكلها بعد ذلك أم لا؟ فالمقصود أن هذا ليس بلازم، قد تأكلها وقد لا تأكلها، وليس في هذا نص، إنما جاء النص في أجسام الأنبياء فقط، وأما غيرهم فقد تطول المدة عليهم لم تؤكل أجسامهم وقد تأكلها الأرض، وفي الحديث الصحيح: إن الأرض تأكل جسم ابن آدم إلا عجب الذنب، وأنه لا يبقى من جسم ابن آدم إلا عجب الذنب؛ وهو العظم الذي في أسفل المقعدة، هذا يبقى، ومنه يحشر بنو آدم، فمقتضى هذا الحديث أن الأجسام تؤكل في المستقبل ولو طالت المدة عليها باقية فمصيرها إلى أن تفنى وتزول إنما جاء في أجسام الأنبياء عليهم الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16522/هل-تاكل-الارض-اجساد-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84109.mp3","categories":["عذاب القبر ونعيمه "]},{"id":17599,"question":"يقول: أعلم أن الأرض لا تأكل أجساد الأنبياء، فهل ينطبق ذلك على أولياء الله الصالحين؟ وإن كان كذلك فهل هناك أحد حصل له شيء من هذا؟","title":"هل تأكل الأرض أجساد الأولياء؟","answer":"الجواب: الأحاديث جاءت في أجسام الأنبياء عليهم الصلاة والسلام، يقول ﷺ: إن الله حرم على الأرض أن تأكل أجساد الأنبياء، أما غيرهم فليس بلازم قد تأكل أجسامهم وقد لا تأكل، وقد شاهد الناس في كثير من البلدان عند بعض الأسباب أجسامًا لم تأكلها الأرض ممن يظن فيهم الصلاح، ولكن لا يدرى هل تأكلها بعد ذلك أم لا؟ فالمقصود أن هذا ليس بلازم، قد تأكلها وقد لا تأكلها، وليس في هذا نص، إنما جاء النص في أجسام الأنبياء فقط، وأما غيرهم فقد تطول المدة عليهم لم تؤكل أجسامهم وقد تأكلها الأرض، وفي الحديث الصحيح: إن الأرض تأكل جسم ابن آدم إلا عجب الذنب، وأنه لا يبقى من جسم ابن آدم إلا عجب الذنب؛ وهو العظم الذي في أسفل المقعدة، هذا يبقى، ومنه يحشر بنو آدم، فمقتضى هذا الحديث أن الأجسام تؤكل في المستقبل ولو طالت المدة عليها باقية فمصيرها إلى أن تفنى وتزول إنما جاء في أجسام الأنبياء عليهم الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16522/هل-تاكل-الارض-اجساد-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84109.mp3","categories":["عذاب القبر ونعيمه "]},{"id":17917,"question":"بالنسبة للسؤال في القبر هل يبدأ من ساعة الوفاة؟ أم من بعد دفن الميت؟","title":"وقت سؤال الميت","answer":"الجواب: الأحاديث الصحيحة ذكر فيها الدفن إذا دفن.. إذا وضع في قبره وانصرف الناس عنه، هذا الذي جاء في الأحاديث، إذا وضع في قبره وانصرف الناس عنه. نعم.","link":"https://binbaz.org.sa/fatwas/16958/وقت-سوال-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78014.mp3","categories":["عذاب القبر ونعيمه "]},{"id":18249,"question":"في سؤاله الثاني يقول هذا السائل سماحة الشيخ: تنقسم حياة الإنسان إلى ثلاثة: حياة الدنيا وهي التي نعيشها، حياة الآخرة وهي معروفة، بين الحياة الدنيا وبين الآخرة حياة البرزخ فما هي حياة البرزخ؟ وهل الإنسان يكون بجسده وروحه فيها؟","title":"حال المسلم والكافر في حياة البرزخ","answer":"الجواب: حياة البرزخ على حسب حياته في الدنيا، المؤمن ينعم في البرزخ، وروحه في الجنة، وجسده يناله بعض النعيم، والكافر روحه تعرض على النار، ويناله نصيبه من العذاب، وينال جسده نصيبه من العذاب، هذه حياة البرزخ، فالمؤمن في سعادة ونعيم. وأخبر النبي ﷺ أن أرواح المؤمنين في الجنة تسرح في الجنة حيث شاءت، وأما الكفار مثلما أخبر الله عن آل فرعون: النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ[غافر:46] فالكفار أرواحهم معذبة وأجسادهم ينالها نصيبها من العذاب حتى يبعث الله الجميع، ثم تصير أرواح المؤمنين إلى الجنة، وأرواح الكفار إلى النار -نسأل الله العافية- مخلدًا فيها، هؤلاء مخلدون في الجنة، وهؤلاء مخلدون في النار، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/17298/حال-المسلم-والكافر-في-حياة-البرزخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78305.mp3","categories":["الرقائق","عذاب القبر ونعيمه "]},{"id":18286,"question":"هل الشهيد في سبيل الله، يأكل ويشرب ويسمع، وهل هو حي يرزق إلى يوم القيامة، كما قال الحق تبارك وتعالى: وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ [آل عمران:169]؟","title":"حال الشهداء في البرزخ","answer":"الجواب: نعم، كما قال الله هم أحياء عند ربهم يعني: أرواح، الأبدان في التراب، وأما أرواحهم فتنقل إلى الجنة ويأكلون فيها ويشربون في الجنة، كما أخبر . نعم.","link":"https://binbaz.org.sa/fatwas/17335/حال-الشهداء-في-البرزخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91203.mp3","categories":["عذاب القبر ونعيمه "]},{"id":18490,"question":"من العراق رسالة بعثت بها إحدى الأخوات من هناك تقول أم داود تسأل وتقول: هل الشخص المتوفى يعرف بما يدور في بيت أهله؟ وكذلك يرى أهله عند زيارتهم له في المقبرة؟إنني والدة شهيد وأبكي كثيرًا وأزوره كل يوم خميس في المقبرة وأطعم الفقراء ولا أعرف قراءة القرآن؛ لأني لا أعرف القراءة، ولكن أقرأ سورة الفاتحة وبعض السور القصار، ولا أصلي وأريد أن أرى ابني في الحلم ولا أستطيع فماذا أفعل؟","title":"حكم القول بأن الميت يعلم من يزوره","answer":"الجواب: المشروع لك الدعاء له إذا كان مات مسلمًا -قتل مسلمًا- الدعاء له والترحم عليه والصدقة عنه، هذا ينفعه كثيرًا. أما الزيارة فليس لك الزيارة، الرسول ﷺ منع النساء من زيارة القبور وقال عليه الصلاة والسلام: زوروا القبور فإنها تذكركم الآخرة وأراد بذلك الرجال، أما النساء فقد ثبت عنه لعن زوارات القبور من النساء. فالواجب عليك ألا تزوريه في المقبرة، ولكن تدعين له في بيتك وفي كل مكان بالمغفرة والرحمة، وتتصدقين عنه إذا تيسر لك صدقة، وأنت على خير إن شاء الله، وأما الزيارة فلا. وعليك أيضًا أن تصلي، عليك أن تتقي الله وأن تصلي؛ فإن الصلاة عمود الإسلام، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر الصلاة عمود الإسلام وأمرها عظيم والله يقول فيها سبحانه في كتابه العظيم القرآن: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى(يعني: العصر) وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] ويقول سبحانه في كتابه العظيم: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]. فالواجب عليك أن تقيمي الصلاة في وقتها، الظهر أربعًا.. العصر أربعًا.. المغرب ثلاثًا.. العشاء أربعًا.. الفجر ثنتين، هذا الواجب عليك وعلى كل مسلم، ومن تركها كفر ولا حول ولا قوة إلا بالله. فالواجب عليك أن تتوبي إلى الله مما سلف، وأن تستقبلي زمانك بالصلاة والمحافظة على دين الله، وأن تسألي عما أشكل عليك من دينك أهل العلم، أو من طريق هذا البرنامج بالمكاتبة وسوف تجدين إن شاء الله في هذا البرنامج ما يكفي ويشفي. وأما كون أهل الميت كونه يطلع على أحوال أهله ويعلم أخبارهم هذا لا دليل عليه، قد قاله بعض الناس في بعض مرائيهم وزعموا أنهم يرون بعض موتاهم وأنهم يخبرونهم ببعض ما قد يقع ولكن هذا لا يعول عليه، المرائي المنامية لا يعول عليها في أشياء من علم الغيب، ولكن على المؤمن أن يحرص على الإحسان إلى أمواته سواء عرفوا أو ما عرفوا، عليه أن يحرص على الدعاء لهم والترحم عليهم وعلى الصدقة عنهم. وقد سئل النبي ﷺ عليه الصلاة والسلام قال له رجل: يا رسول الله! هل بقي من بري أبوي شيء أبرهما به بعد وفاتهما؟ قال:  نعم. الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما -يعني: وصاياهما الشرعية- وإكرام صديقهما وصلة الرحم التي لا توصل إلا بهما فالدعاء للميت والاستغفار له والترحم عليه والصدقة عنه كل هذا ينفعه في حياته وبعد مماته. أما كونهم يعلمون بالزائر فهذا أيضًا محل نظر، فقد جاء في بعض الأحاديث أنه ﷺ قال: ما من عبد يزور أخًا له كان يعرفه في الدنيا فيسلم عليه إلا عرفه ورد عليه السلام هكذا روى ابن عبد البر وابن أبي الدنيا بإسناد جيد عن النبي ﷺ أنه قال: ما من رجل يزور أخًا له كان يعرفه في الدنيا فيسلم عليه إلا عرفه ورد عليه السلام. فالحاصل أنه سواء عرفك أو ما عرفك سواء عرف الزائر أو ما عرف الزائر المهم أنه يزوره ويدعو له، النبي ﷺ قال: زوروا القبور فإنها تذكركم الآخرة فالمهم أنها تنفع الحي، وتعينه على ذكر الآخرة وذكر الموت حتى يستعد للقاء الله، وتنفع الميت من جهة أن الزائر يدعو له ويترحم عليه، ففي الزيارة للقبور مصالح للحي والميت جميعًا. يزورهم ويسلم عليهم ويدعو لهم ثم ينصرف، لا يتمسح بقبورهم ولا يصلي عند قبورهم، ولا يسأل الله بهم، ولكن يدعو لهم يقول: (اللهم اغفر لهم اللهم ارحمهم). كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي الحديث الآخر: يرحم الله المستقدمين منا والمستأخرين اللهم اغفر لأهل بقيع الغرقد يدعو لهم عليه الصلاة والسلام هكذا أمته تتأسى به، فتدعو للأموات، وتسأل الله لهم المغفرة والعافية، وهذا هو المشروع، ويكفي هذا للمؤمن أن يفعل ما شرعه الله وأن يقف عند الحد الشرعي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17590/حكم-القول-بان-الميت-يعلم-من-يزوره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_867/nour_86705.mp3","categories":["زيارة القبور","عذاب القبر ونعيمه "]},{"id":18658,"question":"لهن قضية حول عذاب القبر ونعيمه سماحة الشيخ: سؤالهن على قدر ما استطعن أن يكتبن، يقلن:عندما يدفن الميت هل ترجع روحه إليه في القبر؟ وإذا كان الأمر كذلك، فإلى متى يبقى الميت في العذاب؟أم تصعد روحه إلى السماء العليا؟ وهل تبقى أم يستمر العذاب حتى يوم الحساب؟ أفيدونا؛ لأن الذين ماتوا منذ زمان بعيد منذ قرون مضت هل يبقون في العذاب، أم ينتظر حتى يوم الحساب؟نريد أن توضحوا لنا هذا الأمر، جزاكم الله خيرًا.","title":"إثبات عذاب القبر ونعيمه","answer":"الجواب: القبر إما روضة من رياض الجنة، أو حفرة من حفر النار، كما جاءت به الأحاديث عن رسول الله -عليه الصلاة والسلام- فالمؤمن ينعم في قبره، المؤمن في نعيم في قبره، وروحه في نعيم في الجنة، تنقل إلى الجنة، أرواح المؤمنين تكون في الجنة في شكل طائر يرد الجنة، ويأكل من ثمارها، تكون هذه الأرواح بشكل طائر ترد الجنة، وتأكل من ثمارها. ويردها الله إلى الجسد إذا شاء  عند السؤال، وفي الأوقات الأخرى التي يشاؤها الله -جل وعلا-. وهو في نعيم أبدًا، وهو في نعيم وجسده ما دام باقيًا، فهو في نعيم، يناله نصيب من النعيم، كما يشاء الله سبحانه، والكافر في عذاب روحه في عذاب، وينال جسده نصيبه من العذاب. أما المدة وكيف يعذب؟ هذا إلى الله سبحانه، ولا نعلمها نحن، المدة الله أعلم بها. لكن نعلم أن المؤمن في نعيم، وروحه في نعيم، والكافر في عذاب، أما تفصيل ذلك فيما يتعلق بالعذاب فلم يبلغنا فيه ما يدل على التفصيل إلا أنهم في عذاب، روحه في عذاب، وجسده يناله نصيب من العذاب، نسأل الله العافية. أما العاصي فهو تحت المشيئة، قد يعاقب في قبره، قد يعذب، وقد يعفى عنه، قد يعذب وقتًا دون وقت، فأمره إلى الله -جل وعلا- وقد أخبر النبي ﷺ أنه مر على قبرين، فإذا هما يعذبان، أحدهما يعذب بالنميمة، والثاني يعذب لعدم تنزهه من البول. فالعاصي على خطر إذا مات على المعاصي، ولم يتب، وهو متوعد بالعذاب، لكن قد يعفى عنه لأسباب أعمال صالحة كثيرة، أو بأسباب أخرى، وإذا عُذب، فالله أعلم سبحانه بكيفية العذاب واستمراره وانقطاعه، هذا إلى الله  هو الذي يعلم كل شيء -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17767/اثبات-عذاب-القبر-ونعيمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73505.mp3","categories":["عذاب القبر ونعيمه "]},{"id":18717,"question":"يقول في هذا السؤال هذا السائل سماحة الشيخ عبد العزيز: القبر أول منازل الآخرة، وفيه يكون السؤال لابن آدم عن ربه، ودينه، والرجل الذي بعث إليهم، وبعد السؤال يقال للعبد إن كان من أهل الجنة: انظر إلى مقعدك في النار، أبدلك الله به مقعدًا في الجنة وإن كان من أهل النار يقال عكس ذلك، وعليه يكون العبد قد علم هل هو من أهل الجنة أم من أهل النار؟ ولكن سماحة الشيخ، الآيات القرآنية والأحاديث النبوية التي تتناول يوم القيامة بما فيها من بعث، واستلام للصحائف والحساب والميزان والصراط، كلها تبين بأن ابن آدم لا يعلم هذا المكان من الجنة أو من النار؛ إلا بعد المرور على الصراط. نرجو من سماحتكم أن توضحوا لنا ذلك، مأجورين.","title":"مكان معرفة العبد لمقعده في الجنة أو النار","answer":"الجواب: لا منافاة في هذا كله، المؤمن يرى مقعده من الجنة، حتى يستبشر بذلك، ويجيه من طيبها، وريحها، ويرى مقعده من النار الذي عافاه الله، وصرفه عنه حتى يسر بذلك، وهذا للمؤمن في قبره، وفي الآخرة إذا رأى من حسابه، وأعطي كتابه بيمينه؛ صار إلى منزله في الجنة، والحمد لله ما منافاة، يبشر به في القبر، ويوم القيامة يرشده الله إلى منزله في الجنة بعد انتهاء الحساب، وبعد تجاوز الصراط، الله يرشده حتى يصل إلى منزله في الجنة، هو أدل عليه من منزله في الدنيا، وهذا من رحمة الله، وتيسيره -جل وعلا- ولا منافاة، هو يعلمه بالجنة بإخبار الملائكة له، وهكذا ما وقاه الله من النار، ولكن بعد الحساب والجزاء، وبعد الصراط يرشده الله إلى منزله في الجنة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17846/مكان-معرفة-العبد-لمقعده-في-الجنة-او-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78906.mp3","categories":["الرقائق","عذاب القبر ونعيمه "]}]
